// frontend/src/components/layout/AppLayout.js
import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { usePermissions, ROLE_COLORS, ROLE_ICONS, ROLE_LABELS } from '../../context/PermissionsContext';
import toast from 'react-hot-toast';

// Nav items with required permission
const NAV_ITEMS = [
  { path: '/dashboard',        icon: '📊', label: 'Tableau de bord', module: 'dashboard'  },
  { path: '/projects',         icon: '🏗️', label: 'Projets',         module: null          }, // always visible
  { path: '/planning',         icon: '📅', label: 'Planning',         module: 'planning'   },
  { path: '/journal',          icon: '📓', label: 'Journal',          module: 'journal'    },
  { path: '/budget',           icon: '💰', label: 'Budget & Achats',  module: 'budget'     },
  { path: '/qhse',             icon: '🛡️', label: 'QHSE',             module: 'qhse'       },
  { path: '/documents',        icon: '📁', label: 'Documents',        module: 'documents'  },
  { path: '/contracts/upload', icon: '📄', label: 'Contrats IA',      module: null          }, // always visible
  { path: '/reports',          icon: '📈', label: 'Rapports',         module: 'reports'    },
];

export default function AppLayout({ children }) {
  const { user, logout } = useAuth();
  const { can, role, isSuperAdmin } = usePermissions();
  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    toast.success('Déconnecté avec succès');
    navigate('/');
  };

  const visibleNav = NAV_ITEMS.filter(item =>
    item.module === null || can(item.module)
  );

  const roleColor  = ROLE_COLORS[role]  || ROLE_COLORS.client;
  const roleIcon   = ROLE_ICONS[role]   || '👤';
  const roleLabel  = ROLE_LABELS[role]  || role;

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#0D0D1A' }}>

      {/* ── Sidebar ──────────────────────────────────────────────── */}
      <aside style={{
        width: 248, background: '#0A0A16',
        borderRight: '1px solid rgba(255,255,255,0.06)',
        display: 'flex', flexDirection: 'column',
        height: '100vh', position: 'sticky', top: 0, flexShrink: 0,
      }}>

        {/* Logo */}
        <div style={{ padding: '22px 20px', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
          <Link to="/dashboard" style={{ display: 'flex', alignItems: 'center', gap: 10, textDecoration: 'none' }}>
            <div style={{ width: 34, height: 34, background: 'linear-gradient(135deg, #F59E0B, #D97706)', borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, fontWeight: 900, color: '#0D0D1A', fontFamily: 'Bebas Neue' }}>C</div>
            <span style={{ fontFamily: 'Bebas Neue', fontSize: 22, letterSpacing: 2, color: '#fff' }}>
              BTP<span style={{ color: '#F59E0B' }}>360</span>
            </span>
          </Link>
        </div>

        {/* Role indicator */}
        <div style={{ padding: '12px 16px', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
          <span style={{
            display: 'inline-flex', alignItems: 'center', gap: 6,
            padding: '4px 10px', borderRadius: 100, fontSize: 11, fontWeight: 600,
            color: roleColor.color, background: roleColor.bg, border: `1px solid ${roleColor.border}`,
          }}>
            {roleIcon} {roleLabel}
          </span>
        </div>

        {/* Nav */}
        <nav style={{ flex: 1, padding: '12px 10px', display: 'flex', flexDirection: 'column', gap: 2, overflowY: 'auto' }}>
          {visibleNav.map(item => {
            const active = location.pathname === item.path ||
              (item.path !== '/dashboard' && location.pathname.startsWith(item.path));
            return (
              <Link key={item.path} to={item.path} style={{
                display: 'flex', alignItems: 'center', gap: 10,
                padding: '9px 12px', borderRadius: 8,
                textDecoration: 'none',
                background:  active ? 'rgba(245,158,11,0.1)' : 'transparent',
                color:       active ? '#F59E0B' : '#9CA3AF',
                fontFamily:  'Barlow Condensed', fontSize: 14, fontWeight: 600,
                letterSpacing: 0.3, transition: 'all 0.15s',
                borderLeft: active ? '3px solid #F59E0B' : '3px solid transparent',
              }}
              onMouseEnter={e => { if (!active) e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
              onMouseLeave={e => { if (!active) e.currentTarget.style.background = 'transparent'; }}
              >
                <span style={{ fontSize: 15, width: 20, textAlign: 'center' }}>{item.icon}</span>
                {item.label}
              </Link>
            );
          })}

          {/* Admin section */}
          {isSuperAdmin && (
            <>
              <div style={{ height: 1, background: 'rgba(255,255,255,0.05)', margin: '8px 4px' }} />
              <Link to="/team" style={{
                display: 'flex', alignItems: 'center', gap: 10,
                padding: '9px 12px', borderRadius: 8, textDecoration: 'none',
                background: location.pathname.startsWith('/team') ? 'rgba(245,158,11,0.1)' : 'transparent',
                color:      location.pathname.startsWith('/team') ? '#F59E0B' : '#6B7280',
                fontFamily: 'Barlow Condensed', fontSize: 13, fontWeight: 600, letterSpacing: 0.3,
                borderLeft: location.pathname.startsWith('/team') ? '3px solid #F59E0B' : '3px solid transparent',
              }}>
                <span style={{ fontSize: 15, width: 20, textAlign: 'center' }}>👥</span>
                Équipe
              </Link>
            </>
          )}
        </nav>

        {/* User footer */}
        <div style={{ padding: '14px 16px', borderTop: '1px solid rgba(255,255,255,0.06)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
            <div style={{
              width: 36, height: 36, borderRadius: '50%',
              background: `linear-gradient(135deg, ${roleColor.color}, ${roleColor.color}88)`,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 14, fontWeight: 700, color: '#0D0D1A', flexShrink: 0,
            }}>
              {user?.full_name?.[0]?.toUpperCase() || 'U'}
            </div>
            <div style={{ overflow: 'hidden', flex: 1 }}>
              <p style={{ fontSize: 13, fontWeight: 600, color: '#fff', margin: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {user?.full_name}
              </p>
              <p style={{ fontSize: 11, color: '#6B7280', margin: 0, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {user?.company_name}
              </p>
            </div>
          </div>
          <button onClick={handleLogout}
            style={{ width: '100%', padding: '7px 0', borderRadius: 7, border: '1px solid rgba(255,255,255,0.08)', background: 'transparent', color: '#6B7280', fontSize: 12, cursor: 'pointer', fontFamily: 'Barlow Condensed', letterSpacing: 0.3 }}>
            Déconnexion
          </button>
        </div>
      </aside>

      {/* ── Main ──────────────────────────────────────────────────── */}
      <main style={{ flex: 1, overflow: 'auto', minWidth: 0 }}>
        {children}
      </main>
    </div>
  );
}
